const KEY='mpi_v5_data';const OLD_KEY='mpi_v4_data';let data=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem(OLD_KEY)||'null')||window.SEED_DATA;let festFilter='all',contactFilter='all',tableView=false;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const save=()=>{localStorage.setItem(KEY,JSON.stringify(data));window.cloudSync?.scheduleIran()};
function fmt(d){if(!d)return 'À vérifier';let x=new Date(d+'T12:00:00');return isNaN(x)?d:x.toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'})}
function dateKey(d){if(!d)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(d))return d;let t=String(d).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace('1er','1');let mo={janvier:1,fevrier:2,mars:3,avril:4,mai:5,juin:6,juillet:7,aout:8,septembre:9,octobre:10,novembre:11,decembre:12};let m=t.match(/(\d{1,2})\s+(janvier|fevrier|mars|avril|mai|juin|juillet|aout|septembre|octobre|novembre|decembre)\s+(20\d{2})/);return m?`${m[3]}-${String(mo[m[2]]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`:''}
function page(id){$$('.page').forEach(x=>x.classList.toggle('active',x.id===id));$$('nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===id));let titles={dashboard:"Vue d’ensemble",festivals:"Festivals",calendar:"Calendrier",contacts:"Diffusion & contacts",communication:"Communication"};$('#pageTitle').textContent=titles[id];$('#addBtn').style.display=['festivals','contacts'].includes(id)?'block':'none';$('#addBtn').textContent=id==='festivals'?'+ Ajouter un festival':'+ Ajouter un contact';if(id==='calendar')renderCalendar()}
$$('nav button').forEach(b=>b.onclick=()=>page(b.dataset.page));$$('[data-goto]').forEach(b=>b.onclick=()=>page(b.dataset.goto));
function counts(){return {todo:data.festivals.filter(f=>f.status==='a_inscrire').length,sent:data.festivals.filter(f=>f.status==='inscrit').length,no:data.festivals.filter(f=>f.status==='refuse').length,iran:data.festivals.filter(f=>f.iranExil).length}}
function renderDash(){let c=counts();$('#stats').innerHTML=[['À inscrire',c.todo],['Inscrits',c.sent],['Refusés',c.no],['Iran / Exil',c.iran]].map(x=>`<div class=stat><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join('');
let today=new Date().toISOString().slice(0,10);let todo=data.festivals.filter(f=>f.status==='a_inscrire'&&dateKey(f.deadline)&&dateKey(f.deadline)>=today).sort((a,b)=>dateKey(a.deadline).localeCompare(dateKey(b.deadline))).slice(0,6);$('#nextDeadlines').innerHTML=todo.map(f=>`<div class=minirow><div><b>${f.name}</b><br><small>${f.city||''} ${f.iranExil?'· Iran / Exil':''}</small></div><span class=datechip>${fmt(f.deadline)}</span></div>`).join('')||'<p class=hint>Aucune deadline renseignée.</p>';
let sent=data.festivals.filter(f=>f.status==='inscrit').map(f=>({...f,calcResponse:f.response||approxResponse(f)})).filter(f=>f.calcResponse).sort((a,b)=>a.calcResponse.localeCompare(b.calcResponse)).slice(0,6);$('#nextResponses').innerHTML=sent.map(f=>`<div class=minirow><div><b>${f.name}</b><br><small>${f.response?'Date renseignée':'Date estimée'}</small></div><span class="datechip orangechip">${fmt(f.calcResponse)}</span></div>`).join('')||'<p class=hint>Aucune réponse datée.</p>'}
function approxResponse(f){if(!f.festivalStart)return '';let d=new Date(f.festivalStart+'T12:00:00');d.setDate(d.getDate()-45);return d.toISOString().slice(0,10)}
function statusLabel(s){return s==='inscrit'?'Inscrit':s==='refuse'?'Refusé':'À inscrire'}
function filteredFest(){let q=$('#festivalSearch').value.toLowerCase();let a=data.festivals.filter(f=>(festFilter==='all'||(festFilter==='iran'?f.iranExil:f.status===festFilter))&&JSON.stringify(f).toLowerCase().includes(q));let sort=$('#sortFestival').value;if(sort==='deadline')a.sort((x,y)=>(dateKey(x.deadline)||'9999').localeCompare(dateKey(y.deadline)||'9999'));if(sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name));if(sort==='status')a.sort((x,y)=>x.status.localeCompare(y.status));return a}
function renderFest(){let a=filteredFest();$('#festivalCards').innerHTML=a.map(f=>`<article class="card ${f.status}"><div style="display:flex;justify-content:space-between">${f.iranExil?'<span class=badge>Iran / Exil</span>':'<span></span>'}<span class="status ${f.status}">${statusLabel(f.status)}</span></div><h3>${esc(f.name)}</h3><div class=meta>${esc(f.city||'Ville à vérifier')}${f.country?' · '+esc(f.country):''}<br>${esc(f.dates||'Dates à vérifier')}</div><div class=facts><div class=fact><small>Deadline</small><b>${fmt(f.deadline)}</b></div><div class=fact><small>Prix</small><b>${esc(f.price||'Prix à vérifier')}</b></div><div class=fact><small>Durée acceptée</small><b>${esc(f.duration||'À vérifier')}</b></div><div class=fact><small>Réponse</small><b>${fmt(f.response||approxResponse(f))}</b></div></div><div class=actions>${f.url?`<a href="${esc(f.url)}" target=_blank>Site ↗</a>`:''}<button onclick="editFestival('${f.id}')">Modifier</button><button class=danger onclick="delFestival('${f.id}')">Supprimer</button></div></article>`).join('');
$('#festivalTable').innerHTML=`<table><thead><tr><th>Festival</th><th>Statut</th><th>Iran/Exil</th><th>Ville</th><th>Pays</th><th>Deadline</th><th>Prix</th><th>Durée</th><th></th></tr></thead><tbody>${a.map(f=>`<tr><td><b>${esc(f.name)}</b></td><td>${statusLabel(f.status)}</td><td>${f.iranExil?'Oui':''}</td><td>${esc(f.city)}</td><td>${esc(f.country)}</td><td>${fmt(f.deadline)}</td><td>${esc(f.price)}</td><td>${esc(f.duration)}</td><td><button onclick="editFestival('${f.id}')">Modifier</button></td></tr>`).join('')}</tbody></table>`}
$('#festivalSearch').oninput=renderFest;$('#sortFestival').onchange=renderFest;$$('#statusTabs button').forEach(b=>b.onclick=()=>{$$('#statusTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');festFilter=b.dataset.filter;renderFest()});$('#viewToggle').onclick=()=>{tableView=!tableView;$('#festivalCards').classList.toggle('hidden',tableView);$('#festivalTable').classList.toggle('hidden',!tableView);$('#viewToggle').textContent=tableView?'▦ Cartes':'☷ Tableau'};
function renderContacts(){let q=$('#contactSearch').value.toLowerCase();let a=data.contacts.filter(c=>(contactFilter==='all'||c.type===contactFilter)&&JSON.stringify(c).toLowerCase().includes(q));$('#contactCards').innerHTML=a.map(c=>{let d=c.data||{};return `<article class=contact><div style="display:flex;justify-content:space-between"><span class=type>${c.type}</span>${c.iran?'<span class="badge iranbadge">Iran</span>':''}</div><h3>${esc(c.name)}</h3><p>${esc(d['Activité / ligne éditoriale']||d['Intérêt pour le film (appréciation)']||'')}</p><div class=meta>${esc(d.Pays||'')} ${d.Ville?'· '+esc(d.Ville):''}</div><div class=actions style="margin-top:12px">${d.Site?`<a href="${esc(d.Site)}" target=_blank>Site ↗</a>`:''}<button onclick="editContact('${c.id}')">Modifier</button><button class=danger onclick="delContact('${c.id}')">Supprimer</button></div></article>`}).join('')}
$('#contactSearch').oninput=renderContacts;$$('#contactTabs button').forEach(b=>b.onclick=()=>{$$('#contactTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');contactFilter=b.dataset.type;renderContacts()});
let calDate=new Date(),calView='month';
function calendarEvents(){let mode=$('#calendarRange').value,ev=[];data.festivals.forEach(f=>{if(f.status==='a_inscrire'&&dateKey(f.deadline)&&(mode==='all'||mode==='todo'))ev.push({id:f.id,date:dateKey(f.deadline),type:'todo',name:f.name,label:"Date limite d'inscription"});if(f.status==='inscrit'&&dateKey(f.response||approxResponse(f))&&(mode==='all'||mode==='response'))ev.push({id:f.id,date:dateKey(f.response||approxResponse(f)),type:'response',name:f.name,label:f.response?'Réponse attendue':'Réponse estimée (J-45)'});if(f.festivalStart&&dateKey(f.festivalStart)&&mode==='all')ev.push({id:f.id,date:dateKey(f.festivalStart),type:'festival',name:f.name,label:'Début du festival'})});return ev.sort((a,b)=>a.date.localeCompare(b.date))}
function renderCalendar(){let ev=calendarEvents();$('#calendarList').innerHTML=ev.map(e=>`<div class="event ${e.type}" onclick="editFestival('${e.id}')" title="Ouvrir la fiche festival"><b>${fmt(e.date)}</b><i class=ball></i><div><b>${esc(e.name)}</b><br><small>${e.label}</small></div><span>${e.type==='todo'?'Inscription':e.type==='response'?'Réponse':'Festival'}</span></div>`).join('')||'<p class=hint>Aucune échéance.</p>';let y=calDate.getFullYear(),m=calDate.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),prevDays=new Date(y,m,0).getDate();$('#calLabel').textContent=first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});let cells=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class=dayhead>${x}</div>`);for(let i=0;i<42;i++){let day=i-offset+1,dt,muted=false;if(day<1){dt=new Date(y,m-1,prevDays+day);muted=true}else if(day>days){dt=new Date(y,m+1,day-days);muted=true}else dt=new Date(y,m,day);let key=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0'),items=ev.filter(e=>e.date===key);cells.push(`<div class="daycell ${muted?'muted':''}"><span>${dt.getDate()}</span>${items.slice(0,3).map(e=>`<div class="calevent ${e.type}" onclick="event.stopPropagation();editFestival('${e.id}')" title="Ouvrir la fiche">${esc(e.name)}</div>`).join('')}${items.length>3?`<small>+${items.length-3}</small>`:''}</div>`)}$('#calendarMonth').innerHTML=cells.join('')}
$('#calendarRange').onchange=renderCalendar;
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function openModal(title,html){$('#modalTitle').textContent=title;$('#editForm').innerHTML=html;$('#modal').classList.remove('hidden')}function closeModal(){$('#modal').classList.add('hidden')}
function festivalForm(f={}){return `<div class=formgrid><div class="field wide"><label>Nom</label><input name=name required value="${esc(f.name||'')}"></div><div class=field><label>Statut</label><select name=status><option value=a_inscrire ${f.status==='a_inscrire'?'selected':''}>À inscrire</option><option value=inscrit ${f.status==='inscrit'?'selected':''}>Inscrit</option><option value=refuse ${f.status==='refuse'?'selected':''}>Refusé</option></select></div><div class=field><label>Iran / Exil</label><select name=iranExil><option value=false>Non</option><option value=true ${f.iranExil?'selected':''}>Oui</option></select></div><div class=field><label>Dates du festival</label><input name=dates value="${esc(f.dates||'')}"></div><div class=field><label>Début du festival</label><input type=date name=festivalStart value="${f.festivalStart||''}"></div><div class=field><label>Pays</label><input name=country value="${esc(f.country||'')}"></div><div class=field><label>Ville</label><input name=city value="${esc(f.city||'')}"></div><div class=field><label>Deadline</label><input type=date name=deadline value="${f.deadline||''}"></div><div class=field><label>Réponse envisagée</label><input type=date name=response value="${f.response||''}"></div><div class=field><label>Prix</label><input name=price value="${esc(f.price||'Prix à vérifier')}"></div><div class=field><label>Durée max / section</label><input name=duration value="${esc(f.duration||'À vérifier')}"></div><div class="field wide"><label>Site web</label><input name=url value="${esc(f.url||'')}"></div><div class=field><label>Film produit après</label><input name=producedAfter value="${esc(f.producedAfter||'')}"></div><div class=field><label>Durée minimum</label><input name=minDuration value="${esc(f.minDuration||'')}"></div><div class=field><label>Pays de production admis</label><input name=eligibleCountries value="${esc(f.eligibleCountries||'')}"></div><div class=field><label>Format de projection</label><input name=projectionFormat value="${esc(f.projectionFormat||'')}"></div><div class=field><label>Sous-titrage requis</label><input name=subtitleRequirement value="${esc(f.subtitleRequirement||'')}"></div><div class=field><label>Première / exclusivité</label><input name=premiereRequirement value="${esc(f.premiereRequirement||'')}"></div><div class="field wide"><label>Conditions d’éligibilité</label><textarea name=eligibility>${esc(f.eligibility||'')}</textarea></div><div class="field wide"><label>Notes</label><textarea name=notes>${esc(f.notes||'')}</textarea></div></div><button class=primary type=submit>Enregistrer</button>`}
function editFestival(id){let f=data.festivals.find(x=>x.id===id);openModal(f?'Modifier le festival':'Ajouter un festival',festivalForm(f||{}));$('#editForm').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.iranExil=o.iranExil==='true';if(f)Object.assign(f,o);else data.festivals.push({...o,id:'new-'+Date.now()});save();closeModal();renderAll()}}
function delFestival(id){if(confirm('Supprimer ce festival ?')){data.festivals=data.festivals.filter(x=>x.id!==id);save();renderAll()}}
function editContact(id){let c=data.contacts.find(x=>x.id===id);let d=c?.data||{};openModal(c?'Modifier le contact':'Ajouter un contact',`<div class=formgrid><div class="field wide"><label>Nom</label><input name=name required value="${esc(c?.name||'')}"></div><div class=field><label>Type</label><select name=type>${['Vendeur','Diffuseur','Plateforme','Association','Distributeur'].map(x=>`<option ${c?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class=field><label>Pays</label><input name=Pays value="${esc(d.Pays||'')}"></div><div class=field><label>Ville</label><input name=Ville value="${esc(d.Ville||'')}"></div><div class="field wide"><label>Activité / ligne éditoriale</label><textarea name=activity>${esc(d['Activité / ligne éditoriale']||'')}</textarea></div><div class="field wide"><label>Site</label><input name=Site value="${esc(d.Site||'')}"></div><div class="field wide"><label>Notes / suivi</label><textarea name=notes>${esc(d['Réponse / remarques de suivi']||'')}</textarea></div></div><button class=primary>Enregistrer</button>`);$('#editForm').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target)),obj={id:c?.id||'contact-'+Date.now(),name:o.name,type:o.type,data:{...(c?.data||{}),Pays:o.Pays,Ville:o.Ville,Site:o.Site,'Activité / ligne éditoriale':o.activity,'Réponse / remarques de suivi':o.notes}};if(c)Object.assign(c,obj);else data.contacts.push(obj);save();closeModal();renderAll()}}
function delContact(id){if(confirm('Supprimer ce contact ?')){data.contacts=data.contacts.filter(x=>x.id!==id);save();renderAll()}}
$('#addBtn').onclick=()=>$('.page.active').id==='festivals'?editFestival():editContact();
let assets=JSON.parse(localStorage.getItem('mpi_assets')||'[]');function renderAssets(){$('#assets').innerHTML=assets.map((a,i)=>`<div class=asset><b>${esc(a.label)}</b><br><a href="${esc(a.url)}" target=_blank>${esc(a.url)}</a> <button onclick="assets.splice(${i},1);saveAssets()">×</button></div>`).join('')||'<p class=hint>Aucun lien ajouté.</p>'}function addAsset(){let label=prompt('Nom (ex. Bande-annonce, Dossier de presse)');if(!label)return;let url=prompt('Lien');if(url){assets.push({label,url});saveAssets()}}function saveAssets(){localStorage.setItem('mpi_assets',JSON.stringify(assets));window.cloudSync?.scheduleIran();renderAssets()}
function renderAll(){renderDash();renderFest();renderContacts();renderCalendar();renderAssets()}renderAll();
$('#calMonthBtn').onclick=()=>{calView='month';$('#calendarMonth').classList.remove('hidden');$('#calendarList').classList.add('hidden');$('#calMonthBtn').classList.add('active');$('#calListBtn').classList.remove('active')};$('#calListBtn').onclick=()=>{calView='list';$('#calendarMonth').classList.add('hidden');$('#calendarList').classList.remove('hidden');$('#calListBtn').classList.add('active');$('#calMonthBtn').classList.remove('active')};$('#calPrev').onclick=()=>{calDate.setMonth(calDate.getMonth()-1);renderCalendar()};$('#calNext').onclick=()=>{calDate.setMonth(calDate.getMonth()+1);renderCalendar()};$('#calToday').onclick=()=>{calDate=new Date();renderCalendar()};

// ---- V4: contacts CRM + film master sheet + assisted imports ----
const FILM_KEY='mpi_v4_film';
function normalizeContacts(){
 data.contacts.forEach(c=>{c.data=c.data||{}; let d=c.data;
   if(d['Uniquement Iran ?']==='Oui') c.iran=true;
   c.country=c.country||d.Pays||''; c.city=c.city||d.Ville||'';
   c.email=c.email||d.Email||''; c.phone=c.phone||d.Téléphone||'';
   c.contactName=c.contactName||d['Nom du contact']||'';
   c.contactDate=c.contactDate||dateish(d['Date de contact']);
   c.followupDate=c.followupDate||dateish(d['Date de relance']);
   c.crmStatus=c.crmStatus||((c.contactDate)?'contacte':'a_contacter');
   c.reply=c.reply||'pas_de_reponse';
 })}
function dateish(v){if(!v)return '';let s=String(v);if(/^\d{4}-\d\d-\d\d/.test(s))return s.slice(0,10);return ''}
normalizeContacts();save();

function contactStatusLabel(s){return ({a_contacter:'À contacter',contacte:'Contacté',a_relancer:'À relancer',reponse:'Réponse reçue'})[s]||'À contacter'}
function replyLabel(s){return ({pas_de_reponse:'Pas de réponse',positif:'Positif',negatif:'Négatif',discussion:'En discussion'})[s]||'Pas de réponse'}
function needsFollowup(c){if(!c.contactDate||c.crmStatus==='reponse')return false;let d=new Date(c.followupDate||c.contactDate);return (Date.now()-d.getTime())/86400000>=14}
let contactCountry='all',contactCrm='all',contactIran=false,contactSort='name';

const oldRenderContacts=renderContacts;
renderContacts=function(){
 let q=$('#contactSearch').value.toLowerCase();
 let a=data.contacts.filter(c=>(contactFilter==='all'||c.type===contactFilter)&&(!contactIran||c.iran)&&(contactCountry==='all'||c.country===contactCountry)&&(contactCrm==='all'||c.crmStatus===contactCrm)&&JSON.stringify(c).toLowerCase().includes(q));
 a.sort((x,y)=>contactSort==='country'?(x.country||'').localeCompare(y.country||''):contactSort==='date'?(y.contactDate||'').localeCompare(x.contactDate||''):(x.name||'').localeCompare(y.name||''));
 $('#contactCards').innerHTML=a.map(c=>`<article class=contact><div class=contacttop><span class=type>${c.type}</span>${c.iran?'<span class="badge iran">Iran</span>':''}</div><h3>${esc(c.name)}</h3><div class=meta>${esc(c.country)} ${c.city?'· '+esc(c.city):''}</div><div class="crmline"><span class="crm ${c.crmStatus}">${contactStatusLabel(c.crmStatus)}</span>${needsFollowup(c)?'<span class="crm warn">Relance +14j</span>':''}</div><p>${esc(c.data?.['Activité / ligne éditoriale']||'')}</p><div class=contactdetails>${c.contactName?`<span>👤 ${esc(c.contactName)}</span>`:''}${c.email?`<span>✉ ${esc(c.email)}</span>`:''}${c.phone?`<span>☎ ${esc(c.phone)}</span>`:''}${c.contactDate?`<span>Contact : ${fmt(c.contactDate)}</span>`:''}${c.reply!=='pas_de_reponse'?`<span>Retour : ${replyLabel(c.reply)}</span>`:''}</div><div class=actions style="margin-top:12px">${c.data?.Site?`<a href="${esc(c.data.Site)}" target=_blank>Site ↗</a>`:''}<button onclick="editContactV4('${c.id}')">Modifier</button><button class=danger onclick="delContact('${c.id}')">Supprimer</button></div></article>`).join('')||'<div class=empty>Aucun contact avec ces filtres.</div>';
}
function setupContactFilters(){
 let tb=$('#contacts .toolbar'); if(!tb||$('#crmFilters'))return;
 let countries=[...new Set(data.contacts.map(c=>c.country).filter(Boolean))].sort();
 let wrap=document.createElement('div');wrap.id='crmFilters';wrap.className='filterrow';wrap.innerHTML=`<button id=iranOnly>Iran uniquement</button><select id=countryFilter><option value=all>Tous les pays</option>${countries.map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id=crmFilter><option value=all>Tous les suivis</option><option value=a_contacter>À contacter</option><option value=contacte>Contactés</option><option value=a_relancer>À relancer</option><option value=reponse>Réponse reçue</option></select><select id=contactSort><option value=name>Trier : nom</option><option value=country>Trier : pays</option><option value=date>Trier : date de contact</option></select>`;
 tb.after(wrap);
 $('#iranOnly').onclick=()=>{contactIran=!contactIran;$('#iranOnly').classList.toggle('active',contactIran);renderContacts()};
 $('#countryFilter').onchange=e=>{contactCountry=e.target.value;renderContacts()};
 $('#crmFilter').onchange=e=>{contactCrm=e.target.value;renderContacts()};
 $('#contactSort').onchange=e=>{contactSort=e.target.value;renderContacts()};
}
function editContactV4(id){
 let c=data.contacts.find(x=>x.id===id),d=c?.data||{};
 openModal(c?'Modifier le contact':'Ajouter un contact',`<div class=formgrid><div class="field wide"><label>Organisme</label><input name=name required value="${esc(c?.name||'')}"></div><div class=field><label>Type</label><select name=type>${['Vendeur','Diffuseur','Plateforme','Association','Distributeur'].map(x=>`<option ${c?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class=field><label>Spécifique Iran ?</label><select name=iran><option value=false>Non</option><option value=true ${c?.iran?'selected':''}>Oui</option></select></div><div class=field><label>Pays</label><input name=country value="${esc(c?.country||'')}"></div><div class=field><label>Ville</label><input name=city value="${esc(c?.city||'')}"></div><div class=field><label>Nom du contact</label><input name=contactName value="${esc(c?.contactName||'')}"></div><div class=field><label>Email</label><input type=email name=email value="${esc(c?.email||'')}"></div><div class=field><label>Téléphone</label><input name=phone value="${esc(c?.phone||'')}"></div><div class=field><label>Site</label><input name=Site value="${esc(d.Site||'')}"></div><div class=field><label>Date de contact</label><input type=date name=contactDate value="${c?.contactDate||''}"></div><div class=field><label>Date de relance</label><input type=date name=followupDate value="${c?.followupDate||''}"></div><div class=field><label>État</label><select name=crmStatus>${[['a_contacter','À contacter'],['contacte','Contacté'],['a_relancer','À relancer'],['reponse','Réponse reçue']].map(x=>`<option value=${x[0]} ${c?.crmStatus===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class=field><label>Retour</label><select name=reply>${[['pas_de_reponse','Pas de réponse'],['positif','Positif'],['negatif','Négatif'],['discussion','En discussion']].map(x=>`<option value=${x[0]} ${c?.reply===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field wide"><label>Activité / ligne éditoriale</label><textarea name=activity>${esc(d['Activité / ligne éditoriale']||'')}</textarea></div><div class="field wide"><label>Notes / historique</label><textarea name=notes>${esc(d['Réponse / remarques de suivi']||'')}</textarea></div></div><button class=primary>Enregistrer</button>`);
 $('#editForm').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));let obj={id:c?.id||'contact-'+Date.now(),name:o.name,type:o.type,iran:o.iran==='true',country:o.country,city:o.city,contactName:o.contactName,email:o.email,phone:o.phone,contactDate:o.contactDate,followupDate:o.followupDate,crmStatus:o.crmStatus,reply:o.reply,data:{...(c?.data||{}),Pays:o.country,Ville:o.city,Site:o.Site,'Uniquement Iran ?':o.iran==='true'?'Oui':'Non','Activité / ligne éditoriale':o.activity,'Réponse / remarques de suivi':o.notes}};if(c)Object.assign(c,obj);else data.contacts.push(obj);save();closeModal();setupContactFilters();renderAll()}
}
