function parseFestivalText(txt,url=''){
 let f={url, status:'a_inscrire', iranExil:false}; let t=txt.replace(/\r/g,'');
 const grab=(rx)=>{let m=t.match(rx);return m?m[1].trim():''};
 f.deadline=toISO(grab(/Date limite d['’]inscription(?: des films)?\s*:?\s*\n+\s*(?:~~)?([^\n~]+)/i)||grab(/(?:Final|Standard|Regular|Late)\s+Deadline\s*\n+\s*([^\n]+)/i));
 f.price=grab(/Frais d['’]inscription\s*:?\s*\n+\s*(?:###\s*)?([^\n]+)/i)||'Prix à vérifier';
 f.duration=grab(/Durée maximum[^:]*:\s*([^\n]+)/i)||'À vérifier';
 f.minDuration=grab(/Durée minimum\s*:?\s*([^\n]+)/i);
 f.producedAfter=grab(/Films produits après[^:]*:\s*([^\n]+)/i);
 f.eligibleCountries=grab(/Pays de production\s*:\s*([^\n]+)/i);
 f.projectionFormat=grab(/Format de projection\s*:\s*([^\n]+)/i);
 f.subtitleRequirement=grab(/Sous-?titr(?:age|ages|es)\s*:?\s*([^\n]+)/i);
 f.response=toISO(grab(/Annonce des résultats\s*\n+\s*([^\n]+)/i));
 let title=grab(/(?:DOCFILMDEPOT\s*-\s*)?([^\n]{3,80})\n/i); if(title&&!/Festival entry management/i.test(title))f.name=title;
 f.eligibility=(t.match(/(?:CONDITIONS|CRITÈRES LIBRES)\s*:([\s\S]{0,1600})/i)||[])[1]?.trim()||'';
 return f
}
function toISO(s){if(!s)return '';let x=s.replace(/~~/g,'').trim().toLowerCase().replace('1er','1');let months={janvier:1,février:2,fevrier:2,mars:3,avril:4,mai:5,juin:6,juillet:7,août:8,aout:8,septembre:9,octobre:10,novembre:11,décembre:12,decembre:12};let m=x.match(/(\d{1,2})\s+([a-zéûôîà]+)\s+(\d{4})/);if(m&&months[m[2]])return `${m[3]}-${String(months[m[2]]).padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=x.match(/(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;return ''}
openImport=function(kind){
 let isFilm=kind==='film';
 openModal(isFilm?'Importer la fiche du film':'Importer un festival',isFilm?`<div class=importbox><p>L'import direct du profil privé FilmFreeway n'est pas accessible depuis cette V5 locale. Tu peux néanmoins conserver son URL ici et remplir la fiche maître une seule fois.</p><div class=field><label>URL FilmFreeway</label><input name=importUrl type=url required></div><button class=primary>Enregistrer le lien</button></div>`:`<div class=importbox><p><b>Import FilmFreeway / Docfilmdepot</b></p><p>1. Colle l'URL. 2. Copie le texte de la page du festival dans la grande zone ci-dessous. La V5 extrait automatiquement les champs qu'elle reconnaît, puis ouvre la fiche pour vérification.</p><div class=field><label>URL du festival</label><input name=importUrl type=url placeholder="https://..."></div><div class=field><label>Contenu de la fiche</label><textarea name=pageText class=bigtext placeholder="Sélectionne le contenu de la page FilmFreeway ou Docfilmdepot, copie, puis colle ici…"></textarea></div><button class=primary>Analyser et préremplir</button></div>`);
 $('#editForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),url=fd.get('importUrl')||'';if(isFilm){let film=JSON.parse(localStorage.getItem(FILM_KEY)||'{}');film.sourceUrl=url;localStorage.setItem(FILM_KEY,JSON.stringify(film));window.cloudSync?.scheduleIran();closeModal();loadFilm();return}let parsed=parseFestivalText(fd.get('pageText')||'',url);closeModal();editFestival();setTimeout(()=>{Object.entries(parsed).forEach(([k,v])=>{let el=$('#editForm [name="'+k+'"]');if(el&&v!==undefined)el.value=typeof v==='boolean'?String(v):v})},0)}
}

