 $('#mlPrev')?.addEventListener('click',()=>{mlDate.setMonth(mlDate.getMonth()-1);renderMlCalendar()});$('#mlNext')?.addEventListener('click',()=>{mlDate.setMonth(mlDate.getMonth()+1);renderMlCalendar()});$('#mlToday')?.addEventListener('click',()=>{mlDate=new Date();mlDate.setDate(1);renderMlCalendar()});
 renderMl();
