function setResKind(k){resKind=k;$('#tabResidences')?.classList.toggle('active',k==='residence');$('#tabAides')?.classList.toggle('active',k==='aide');let b=$('#addResidenceBtn');if(b)b.textContent=k==='residence'?'+ Ajouter une résidence':'+ Ajouter une aide';renderResidences()}
renderResidences=function(){let box=$('#residenceCards');if(!box)return;let q=($('#resSearch')?.value||'').toLowerCase(),st=$('#resStatus')?.value||'all';let a=ml.residences.filter(r=>(r.kind||'residence')===resKind&&(st==='all'||r.status===st)&&JSON.stringify(r).toLowerCase().includes(q)).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));box.innerHTML=a.map(r=>`<article class=festival><div class=festtop><span class="status ${r.status}">${resStatusLabel(r.status)}</span><span class=datepill>${mlFmt(r.deadline)}</span></div><div class="kindlabel ${r.kind||'residence'}">${(r.kind||'residence')==='residence'?'RÉSIDENCE':'AIDE / BOURSE'}</div><h3>${esc(r.name)}</h3><div class=meta>${esc(r.org||'')}${r.place?' · '+esc(r.place):''}</div>${r.residenceDates?`<p><b>${(r.kind||'residence')==='residence'?'Dates':'Dépôt'} :</b> ${esc(r.residenceDates)}</p>`:''}${r.amount?`<p><b>${(r.kind||'residence')==='residence'?'Prise en charge':'Montant'} :</b> ${esc(r.amount)}</p>`:''}${r.eligibility?`<p><b>Éligibilité :</b> ${esc(r.eligibility)}</p>`:''}${r.notes?`<details><summary>Infos / dossier demandé</summary><p>${esc(r.notes)}</p></details>`:''}${r.verified?`<small class=verified>Vérifié le ${mlFmt(r.verified)}</small>`:''}<div class=actions>${r.url?`<a href="${esc(r.url)}" target=_blank>Site officiel ↗</a>`:''}<button onclick="editResidence('${r.id}')">Modifier</button><button class=danger onclick="ml.residences=ml.residences.filter(x=>x.id!=='${r.id}');saveMl()">Supprimer</button></div></article>`).join('')||`<div class=empty>Aucune ${resKind==='residence'?'résidence':'aide'} pour le moment.</div>`}
editResidence=function(id){let r=ml.residences.find(x=>x.id===id)||{kind:resKind};let isA=(r.kind||resKind)==='aide';openModal(id?'Modifier':'Ajouter '+(isA?'une aide / bourse':'une résidence'),`<div class=formgrid><div class=field><label>Type</label><select name=kind><option value=residence ${!isA?'selected':''}>Résidence</option><option value=aide ${isA?'selected':''}>Aide / bourse</option></select></div><div class="field wide"><label>Nom</label><input name=name required value="${esc(r.name||'')}"></div><div class=field><label>Organisme</label><input name=org value="${esc(r.org||'')}"></div><div class=field><label>Lieu</label><input name=place value="${esc(r.place||'')}"></div><div class=field><label>Deadline de candidature</label><input type=date name=deadline required value="${r.deadline||''}"></div><div class=field><label>${isA?'Session / période de dépôt':'Dates de résidence'}</label><input name=residenceDates value="${esc(r.residenceDates||'')}"></div><div class="field wide"><label>${isA?'Montant / nature de l’aide':'Prise en charge (hébergement, repas, voyage…)'}</label><input name=amount value="${esc(r.amount||'')}"></div><div class=field><label>Statut</label><select name=status>${[['a_etudier','À étudier'],['a_preparer','À préparer'],['depose','Déposé'],['accepte','Accepté'],['refuse','Refusé']].map(x=>`<option value=${x[0]} ${r.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field wide"><label>Site / appel officiel</label><input type=url name=url value="${esc(r.url||'')}"></div><div class="field wide"><label>Éligibilité / conditions</label><textarea name=eligibility>${esc(r.eligibility||'')}</textarea></div><div class="field wide"><label>Pièces demandées / infos utiles</label><textarea name=notes>${esc(r.notes||'')}</textarea></div></div><button class=primary>Enregistrer</button>`);$('#editForm').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));o.id=id||'res-'+Date.now();o.verified=r.verified||'';if(id)Object.assign(r,o);else ml.residences.push(o);saveMl();closeModal();setResKind(o.kind)}}
document.addEventListener('DOMContentLoaded',()=>{$('#tabResidences')?.addEventListener('click',()=>setResKind('residence'));$('#tabAides')?.addEventListener('click',()=>setResKind('aide'));$('#addResidenceBtn').onclick=()=>editResidence();setResKind('residence')});

