function dateInRange(ds,a,b){return ds>=a&&ds<=(b||a)}
renderMlCalendar=function(){
 let box=$('#mlCalendar');if(!box)return;let y=mlDate.getFullYear(),m=mlDate.getMonth();
 $('#mlMonthTitle').textContent=mlDate.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});
 let first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),cells=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class=weekday>${x}</div>`);
 for(let i=0;i<offset;i++)cells.push('<div class="day mutedday"></div>');
 for(let d=1;d<=days;d++){let ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
  let auto=ml.residences.filter(x=>x.deadline===ds).map(x=>({title:x.name,type:x.kind==='aide'?'aid':'residence',auto:true,id:x.id}));
  let manual=ml.events.filter(x=>dateInRange(ds,x.startDate||x.date,x.endDate||x.date));
  let evs=[...auto,...manual];
  cells.push(`<div class=day onclick="if(event.target===this||event.target.tagName==='B')quickMlEventV10('${ds}')"><b>${d}</b>${evs.map(e=>`<div class="mlevent ${e.type}" ${e.auto?'':`onclick="event.stopPropagation();editMlEventV10('${e.id}')"`}>${esc(e.title)}</div>`).join('')}</div>`)
 } box.innerHTML=cells.join('')
}
