// ---- V12 clean UX patch ----
let resTypeFilterV12='all';
function setResTypeFilterV12(v){resTypeFilterV12=v;['All','Aides','Residences'].forEach(k=>document.getElementById('filter'+k)?.classList.toggle('active',v===({All:'all',Aides:'aide',Residences:'residence'}[k])));renderResidencesV12()}
function renderResidencesV12(){let box=$('#residenceCards');if(!box)return;let q=($('#resSearch')?.value||'').toLowerCase(),st=$('#resStatus')?.value||'all';let a=ml.residences.filter(r=>{let k=r.kind||'residence';return(resTypeFilterV12==='all'||k===resTypeFilterV12)&&(st==='all'||r.status===st)&&JSON.stringify(r).toLowerCase().includes(q)}).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));box.innerHTML=a.map(r=>`<article class="festival ${r.kind==='aide'?'aidcardv12':'rescardv12'}"><div class=festtop><span class="status ${r.status}">${resStatusLabel(r.status)}</span><span class=datepill>${mlFmt(r.deadline)}</span></div><div class="kindlabel ${r.kind||'residence'}">${r.kind==='aide'?'AIDE / BOURSE':'RÉSIDENCE'}</div><h3>${esc(r.name)}</h3><div class=meta>${esc(r.org||'')}${r.place?' · '+esc(r.place):''}</div>${r.residenceDates?`<p><b>Dates / période :</b> ${esc(r.residenceDates)}</p>`:''}${r.amount?`<p><b>Montant / prise en charge :</b> ${esc(r.amount)}</p>`:''}${r.eligibility?`<p><b>Éligibilité :</b> ${esc(r.eligibility)}</p>`:''}${r.notes?`<details><summary>Infos / dossier demandé</summary><p>${esc(r.notes)}</p></details>`:''}<div class=actions>${r.url?`<a href="${esc(r.url)}" target=_blank>Site officiel ↗</a>`:''}<button onclick="editResidenceV12('${r.id}')">Modifier</button><button class=danger onclick="ml.residences=ml.residences.filter(x=>x.id!=='${r.id}');ml.tasks=ml.tasks.filter(t=>t.linkedAidId!=='${r.id}');saveMl()">Supprimer</button></div></article>`).join('')||'<div class=empty>Aucun élément dans ce filtre.</div>'}
function syncAidTaskV12(aid,urgent){let t=ml.tasks.find(x=>x.linkedAidId===aid.id),d={id:t?.id||'task-aid-'+aid.id,title:'Préparer — '+aid.name,category:'writing',due:aid.deadline||'',priority:urgent?'Haute':'Normale',done:t?.done||false,linkedAidId:aid.id,notes:'Créée automatiquement depuis l’aide / bourse.'};t?Object.assign(t,d):ml.tasks.push(d)}
function editResidenceV12(id){let r=ml.residences.find(x=>x.id===id)||{kind:'residence'},isAid=(r.kind==='aide'),linked=ml.tasks.find(t=>t.linkedAidId===r.id);openModal(id?'Modifier':'Ajouter',`<div class=formgrid><div class=field><label>Type</label><select name=kind id=kindV12><option value=residence ${!isAid?'selected':''}>Résidence</option><option value=aide ${isAid?'selected':''}>Aide / bourse</option></select></div><div class="field wide"><label>Nom</label><input name=name required value="${esc(r.name||'')}"></div><div class=field><label>Organisme</label><input name=org value="${esc(r.org||'')}"></div><div class=field><label>Lieu</label><input name=place value="${esc(r.place||'')}"></div><div class=field><label>Deadline</label><input type=date name=deadline value="${r.deadline||''}"></div><div class=field><label>Dates / période</label><input name=residenceDates value="${esc(r.residenceDates||'')}"></div><div class="field wide"><label>Montant / prise en charge</label><input name=amount value="${esc(r.amount||'')}"></div><div class=field><label>Statut</label><select name=status>${[['a_etudier','À étudier'],['a_preparer','À préparer'],['depose','Déposé'],['accepte','Accepté'],['refuse','Refusé']].map(x=>`<option value=${x[0]} ${r.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field wide"><label>Site / appel officiel</label><input type=url name=url value="${esc(r.url||'')}"></div><div class="field wide"><label>Éligibilité</label><textarea name=eligibility>${esc(r.eligibility||'')}</textarea></div><div class="field wide"><label>Notes</label><textarea name=notes>${esc(r.notes||'')}</textarea></div><div id=aidUrgencyV12 class="field wide aidurgentv12" style="${isAid?'':'display:none'}"><b>Tâche d’écriture créée automatiquement</b><p>« Préparer — nom de l’aide » avec la même deadline.</p><label class=urgentcheckv12><input type=checkbox name=urgent ${linked?.priority==='Haute'?'checked':''}> 🔥 C’est urgent</label></div></div><button class=primary>Enregistrer</button>`);$('#kindV12').onchange=e=>$('#aidUrgencyV12').style.display=e.target.value==='aide'?'block':'none';$('#editForm').onsubmit=e=>{e.preventDefault();let fd=new FormData(e.target),urgent=fd.has('urgent'),o=Object.fromEntries(fd);delete o.urgent;o.id=id||'res-'+Date.now();o.verified=r.verified||'';if(id)Object.assign(r,o);else{r=o;ml.residences.push(r)}if(o.kind==='aide')syncAidTaskV12(r,urgent);else ml.tasks=ml.tasks.filter(t=>t.linkedAidId!==r.id);saveMl();closeModal();renderResidencesV12()}}
editResidence=editResidenceV12;renderResidences=renderResidencesV12;
// Agenda V12: day click creates range; event click opens detail/edit form.
function openMlEventV12(id){editMlEventV10(id)}
renderMlCalendar=function(){let box=$('#mlCalendar');if(!box)return;let y=mlDate.getFullYear(),m=mlDate.getMonth();$('#mlMonthTitle').textContent=mlDate.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});let first=new Date(y,m,1),offset=(first.getDay()+6)%7,days=new Date(y,m+1,0).getDate(),cells=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class=weekday>${x}</div>`);for(let i=0;i<offset;i++)cells.push('<div class="day mutedday"></div>');for(let d=1;d<=days;d++){let ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;let auto=ml.residences.filter(x=>x.deadline===ds).map(x=>({title:x.name,type:x.kind==='aide'?'aid':'residence',auto:true})),manual=ml.events.filter(x=>dateInRange(ds,x.startDate||x.date,x.endDate||x.date));cells.push(`<div class=day onclick="if(event.target===this||event.target.tagName==='B')quickMlEventV10('${ds}')"><b>${d}</b>${[...auto,...manual].map(e=>`<div class="mlevent ${e.type}" ${e.auto?'title="Deadline automatique — modifiable depuis Résidences & aides"':`onclick="event.stopPropagation();openMlEventV12('${e.id}')" title="Cliquer pour voir / modifier"`}>${esc(e.title)}</div>`).join('')}</div>`)}box.innerHTML=cells.join('')}
document.addEventListener('DOMContentLoaded',()=>{document.getElementById('filterAll')?.addEventListener('click',()=>setResTypeFilterV12('all'));document.getElementById('filterAides')?.addEventListener('click',()=>setResTypeFilterV12('aide'));document.getElementById('filterResidences')?.addEventListener('click',()=>setResTypeFilterV12('residence'));document.getElementById('addResidenceBtn').onclick=()=>editResidenceV12();document.getElementById('resSearch')?.addEventListener('input',renderResidencesV12);document.getElementById('resStatus')?.addEventListener('change',renderResidencesV12);setResTypeFilterV12('all')});
